"""Date-window membership for the date_window fixture."""

from __future__ import annotations


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""

    # Validate and parse target_date
    target = _parse_and_validate_date(target_date)

    # Validate and parse all windows, checking for start > end constraint
    parsed_windows = []
    for start, end in windows:
        start_parsed = _parse_and_validate_date(start)
        end_parsed = _parse_and_validate_date(end)

        # Check that start <= end
        if start_parsed > end_parsed:
            raise ValueError(f"Invalid window: start date {start} is after end date {end}")

        parsed_windows.append((start_parsed, end_parsed))

    # Check if target falls within any window
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False


def _parse_and_validate_date(date_str: str) -> tuple[int, int, int]:
    """Parse and validate a date string in YYYY-MM-DD format.

    Returns a tuple of (year, month, day) if valid.
    Raises ValueError if the date is malformed or impossible.
    """

    # Check format: must be exactly 10 characters
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str}")

    # Check structure: YYYY-MM-DD
    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Invalid date format: {date_str}")

    try:
        year_str = date_str[0:4]
        month_str = date_str[5:7]
        day_str = date_str[8:10]

        # Parse components
        year = int(year_str)
        month = int(month_str)
        day = int(day_str)

        # Validate that strings had proper zero-padding
        if year_str != f"{year:04d}" or month_str != f"{month:02d}" or day_str != f"{day:02d}":
            raise ValueError(f"Invalid date format (missing zero padding): {date_str}")

    except ValueError as e:
        if "Invalid date format" in str(e):
            raise
        raise ValueError(f"Invalid date format: {date_str}")

    # Validate month range
    if month < 1 or month > 12:
        raise ValueError(f"Invalid month in date: {date_str}")

    # Validate day range based on month and leap year
    if day < 1:
        raise ValueError(f"Invalid day in date: {date_str}")

    days_in_month = _days_in_month(year, month)
    if day > days_in_month:
        raise ValueError(f"Invalid day in date: {date_str}")

    return (year, month, day)


def _is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)


def _days_in_month(year: int, month: int) -> int:
    """Return the number of days in a given month of a given year."""
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    elif month in (4, 6, 9, 11):
        return 30
    elif month == 2:
        return 29 if _is_leap_year(year) else 28
    else:
        raise ValueError(f"Invalid month: {month}")
